CREATE TYPE "RemoteAuthorityReplicaState" AS ENUM ('joining', 'required', 'draining');
CREATE TYPE "RemoteAuthoritySigningState" AS ENUM ('reserved', 'signed', 'finalized', 'aborted');
CREATE TYPE "RemoteAuthorityFenceState" AS ENUM ('open', 'closing', 'frozen');
CREATE TYPE "RemoteAuthorityTransitionState" AS ENUM ('reserved', 'status_signed', 'committed', 'aborted');
CREATE TABLE "RemoteAuthorityReplicaMembership" ("deploymentId" TEXT NOT NULL,"membershipGeneration" BIGINT NOT NULL,"replicaId" TEXT NOT NULL,"replicaGeneration" BIGINT NOT NULL,"state" "RemoteAuthorityReplicaState" NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RemoteAuthorityReplicaMembership_pkey" PRIMARY KEY ("deploymentId","replicaId"));
CREATE INDEX "RemoteAuthorityReplicaMembership_deploymentId_membershipGeneration_state_idx" ON "RemoteAuthorityReplicaMembership"("deploymentId","membershipGeneration","state");
CREATE TABLE "RemoteAuthoritySigningJournal" ("mintId" TEXT NOT NULL,"deploymentId" TEXT NOT NULL,"signingGeneration" BIGINT NOT NULL,"kid" TEXT NOT NULL,"claimsHash" TEXT NOT NULL,"state" "RemoteAuthoritySigningState" NOT NULL,"providerRequestId" TEXT NOT NULL,"signatureP1363" TEXT,"compactJws" TEXT,"signedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RemoteAuthoritySigningJournal_pkey" PRIMARY KEY ("mintId"));
CREATE UNIQUE INDEX "RemoteAuthoritySigningJournal_providerRequestId_key" ON "RemoteAuthoritySigningJournal"("providerRequestId");
CREATE UNIQUE INDEX "RemoteAuthoritySigningJournal_deploymentId_mintId_claimsHash_key" ON "RemoteAuthoritySigningJournal"("deploymentId","mintId","claimsHash");
CREATE INDEX "RemoteAuthoritySigningJournal_deploymentId_kid_state_idx" ON "RemoteAuthoritySigningJournal"("deploymentId","kid","state");
CREATE TABLE "RemoteAuthoritySigningFence" ("deploymentId" TEXT NOT NULL,"kid" TEXT NOT NULL,"signingGeneration" BIGINT NOT NULL,"state" "RemoteAuthorityFenceState" NOT NULL,"cutoff" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RemoteAuthoritySigningFence_pkey" PRIMARY KEY ("deploymentId","kid"));
CREATE TABLE "RemoteAuthorityLifecycleTransition" ("transitionId" TEXT NOT NULL,"deploymentId" TEXT NOT NULL,"state" "RemoteAuthorityTransitionState" NOT NULL,"fromRevision" BIGINT NOT NULL,"toRevision" BIGINT NOT NULL,"fromDigest" TEXT NOT NULL,"toDigest" TEXT NOT NULL,"fromAuthorityEpoch" BIGINT NOT NULL,"toAuthorityEpoch" BIGINT NOT NULL,"fromCurrentKid" TEXT NOT NULL,"toCurrentKid" TEXT NOT NULL,"statusGeneration" BIGINT NOT NULL,"statusBodyDigest" TEXT NOT NULL,"signingGeneration" BIGINT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RemoteAuthorityLifecycleTransition_pkey" PRIMARY KEY ("transitionId"));
CREATE INDEX "RemoteAuthorityLifecycleTransition_deploymentId_state_idx" ON "RemoteAuthorityLifecycleTransition"("deploymentId","state");
